--  44_bank_fenn9.sql : 9-CU SINIF - FIZIKA, KIMYA, BIOLOGIYA,
--                      COGRAFIYA
--
--  BU FAYL ELLE YAZILMIR - tools/fenn9.py yaradir:
--      python3 tools/fenn9.py
--
--  Fizika 6 + Kimya 6 + Biologiya 8 + Cografiya 8
--  = 28 movzu x 30 = 840.  ext_key: fiz9-/kim9-/bio9-/cog9-...
--  ON SERT: 41_movzular_orta9.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where (s.slug, t.slug) in (('fizika','fiz-9-isiq'),
                                ('kimya','kim-9-uzvi'),
                                ('biologiya','bio-9-huceyre'),
                                ('cografiya','cog-9-relyef'))
     having count(*) = 4) then
    raise exception 'ONCE 41_movzular_orta9.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'fiz9-%' or q.ext_key like 'kim9-%'
        or q.ext_key like 'bio9-%' or q.ext_key like 'cog9-%');

