('cog9-iqtisadiyyat#22','cografiya','cog-9-iqtisadiyyat',2,4,'Aqrar ölkə hansı ölkəyə deyilir?','İqtisadiyyatında kənd təsərrüfatı üstünlük təşkil edən ölkə aqrar ölkədir.',array['Kənd təsərrüfatı üstünlük təşkil edən ölkəyə','Yalnız sənayesi olan ölkəyə','Dənizsiz ölkəyə','Ən böyük ölkəyə'],1),
('cog9-iqtisadiyyat#23','cografiya','cog-9-iqtisadiyyat',2,4,'Sənayecə yüksək inkişaf etmiş ölkəyə misal hansıdır?','Almaniya dünyanın aparıcı sənaye ölkələrindəndir.',array['Almaniya','Çad','Nepal','Monqolustan'],1),
('cog9-iqtisadiyyat#24','cografiya','cog-9-iqtisadiyyat',2,4,'Rəqabət bazar iqtisadiyyatında hansı rolu oynayır?','Rəqabət keyfiyyəti yüksəldir və qiymətləri tənzimləyir.',array['Keyfiyyəti artırır, qiyməti tənzimləyir','Malları bahalaşdırır yalnız','İstehsalı dayandırır','Heç bir rolu yoxdur'],1),
('cog9-iqtisadiyyat#25','cografiya','cog-9-iqtisadiyyat',2,4,'Vergilər dövlət üçün nə üçün lazımdır?','Vergilər dövlət büdcəsini formalaşdırır - məktəb, xəstəxana, yollar onunla tikilir.',array['Büdcəni formalaşdırmaq üçün','Əhalini cəzalandırmaq üçün','Pulu məhv etmək üçün','Heç bir səbəb yoxdur'],1),
('cog9-iqtisadiyyat#26','cografiya','cog-9-iqtisadiyyat',2,4,'Sahibkarlıq nədir?','Sahibkarlıq gəlir əldə etmək məqsədilə təşəbbüskar fəaliyyətdir.',array['Gəlir məqsədilə təşəbbüskar fəaliyyət','Yalnız dövlət qulluğu','İstirahət növü','İdman yarışı'],1),
('cog9-iqtisadiyyat#27','cografiya','cog-9-iqtisadiyyat',2,4,'Alternativ enerji mənbələrinə hansılar aiddir?','Günəş və külək enerjisi alternativ - bərpa olunan mənbələrdir.',array['Günəş və külək','Neft və qaz','Kömür və torf','Benzin və mazut'],1),
('cog9-iqtisadiyyat#28','cografiya','cog-9-iqtisadiyyat',3,4,'Əmək məhsuldarlığı nədir?','Məhsuldarlıq vahid vaxtda istehsal olunan məhsulun miqdarıdır.',array['Vahid vaxtda istehsal olunan məhsulun miqdarı','İşçilərin ümumi sayı','Zavodun sahəsi','İş gününün uzunluğu'],1),
('cog9-iqtisadiyyat#29','cografiya','cog-9-iqtisadiyyat',2,4,'Regionların sosial-iqtisadi inkişafı dövlət proqramlarının məqsədi nədir?','Proqramlar bölgələrdə iqtisadiyyatı canlandırmağa və məşğulluğa xidmət edir.',array['Bölgələrdə iqtisadiyyatı canlandırmaq','Yalnız paytaxtı böyütmək','Kəndləri boşaltmaq','Sərhədləri bağlamaq'],1),
('cog9-iqtisadiyyat#30','cografiya','cog-9-iqtisadiyyat',2,4,'«Made in Azerbaijan» markası hansı məqsədə xidmət edir?','Marka yerli məhsulların dünya bazarında tanıdılmasına xidmət edir.',array['Yerli məhsulların dünyada tanıdılmasına','Xarici malların gizlədilməsinə','Qiymətlərin artırılmasına','İdxalın dayandırılmasına'],1)
),
ins as (
  insert into public.questions
    (ext_key, owner_type, subject_id, level_id, topic_id, kind,
     body, explanation, difficulty, quarter, status)
  select d.ext, 'platform', s.id, l.id, tp.id, 'single',
         d.body, d.why, d.diff, d.rub, 'published'
    from d
    join public.subjects s on s.slug = d.fenn
    join public.programs p on p.slug = 'orta'
    join public.levels   l on l.program_id = p.id and l.code = '9'
    join public.topics   tp on tp.subject_id = s.id and tp.slug = d.topic
  on conflict (ext_key) do update
    set body = excluded.body, explanation = excluded.explanation,
        difficulty = excluded.difficulty, quarter = excluded.quarter,
        topic_id = excluded.topic_id, level_id = excluded.level_id,
        subject_id = excluded.subject_id, status = 'published'
  returning id, ext_key
)
insert into public.question_options (question_id, ord, body, is_correct)
select ins.id, o.ord, o.txt, o.ord = d.correct
  from ins
  join d on d.ext = ins.ext_key,
  lateral unnest(d.opts) with ordinality as o(txt, ord);

do $$
declare n int; k int;
begin
  select count(*) into n from public.questions
   where owner_type = 'platform'
     and (ext_key like 'fiz9-%' or ext_key like 'kim9-%'
          or ext_key like 'bio9-%' or ext_key like 'cog9-%');
  if n <> 840 then
    raise exception 'fenn9 suallari: 840 gozlenilirdi, % tapildi', n;
  end if;
  select count(*) into k from public.questions q
   where (q.ext_key like 'fiz9-%' or q.ext_key like 'kim9-%'
          or q.ext_key like 'bio9-%' or q.ext_key like 'cog9-%')
     and ((select count(*) from public.question_options o
            where o.question_id = q.id) <> 4
       or (select count(*) from public.question_options o
            where o.question_id = q.id and o.is_correct) <> 1);
  if k > 0 then
    raise exception '% sualda variant qurulusu sehvdir', k;
  end if;
  select count(distinct topic_id) into k from public.questions
   where ext_key like 'fiz9-%' or ext_key like 'kim9-%'
      or ext_key like 'bio9-%' or ext_key like 'cog9-%';
  if k <> 28 then
    raise exception 'movzu sayi 28 deyil: %', k;
  end if;
  raise notice '9-cu sinif fenn banki: % sual, 28 movzu (fiz, kim, bio, cog).', n;
end $$;
